use crate::{Action, Actor, Book, Focus, Genre, Register, RustForm, Signal, Story, StoryError};

pub fn apply(story: &mut Story) -> Result<(), StoryError> {
    genesis(story)?;
    exodus(story)?;
    leviticus(story)?;
    numbers(story)?;
    deuteronomy(story)?;
    Ok(())
}

